@RestController
public class AccountController {
    @Autowired AccountRepository repo;

    @GetMapping("/accounts")
    public List<Account> search(@RequestParam String name) {
        return repo.findAll().stream()
            .filter(a -> a.getName().contains(name))
            .collect(Collectors.toList());
