This cache is used by hundreds of goroutines. Under `go test -race` it occasionally reports races, and in production we sometimes see the loader called multiple times for the same key and rare "concurrent map read and map write" crashes. Identify every concurrency bug, explain the interleaving that triggers each, and provide a corrected implementation that guarantees at most one concurrent load per key, does not hold the global lock during `load`, and does not cache errors.

```go
type Cache struct {
    mu    sync.RWMutex
    data  map[string]*entry
    load  func(string) (string, error)
}

type entry struct {
    once sync.Once
    val  string
    err  error
}

func (c *Cache) Get(k string) (string, error) {
    c.mu.RLock()
    e, ok := c.data[k]
    c.mu.RUnlock()
    if !ok {
        e = &entry{}
        c.mu.Lock()
        c.data[k] = e
        c.mu.Unlock()
    }
    e.once.Do(func() {
        e.val, e.err = c.load(k)
        if e.err != nil {
            delete(c.data, k)
        }
    })
    return e.val, e.err
}
```

